extension Engine where Policy == StaticHostHttpPolicy {
    /// Raises `host.http.fetch.request` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
    /// constructed inconsistently (NL-to-IR Item C1 Path A). Both carriers are
    /// filled: the typed one a native expression reads, and `data`, which is what
    /// every other reader of `_event.data` binds it from.
    public func raiseHostHttpFetchRequest(method: String, url: String, headers: String, body: String) {
        raiseExternalWithMeta(
            EventWithMetadata(
                StaticHostHttpEvent.hostHttpFetchRequest,
                metadata: EventMetadata(
                    data: payloadJSON(.text("method", method), .text("url", url), .text("headers", headers), .text("body", body)),
                    eventType: .externalEvent,
                    typedPayload: StaticHostHttpHostHttpFetchRequestPayload(method: method, url: url, headers: headers, body: body)
                )
            )
        )
    }
}


/// `sce:request`: the record the host is asked to start `<invoke id="fetch">`
/// with (SCE Accepted Subset §2.12).
public struct StaticHostHttpFetchRequest: Equatable, Sendable {
    public var method: String
    public var url: String
    public var headers: String
    public var body: String

    public init(method: String, url: String, headers: String, body: String) {
        self.method = method
        self.url = url
        self.headers = headers
        self.body = body
    }
}

/// `sce:result`: the record the host completes `<invoke id="fetch">`
/// with (SCE Accepted Subset §2.12).
public struct StaticHostHttpFetchResult: Equatable, Sendable {
    public var error: String
    public var status: UInt16
    public var headers: String
    public var body: String

    public init(error: String, status: UInt16, headers: String, body: String) {
        self.error = error
        self.status = status
        self.headers = headers
        self.body = body
    }

    /// The JSON `done.invoke.fetch` carries this record as, in the schema's order.
    public var wire: String {
        payloadJSON(.text("error", error), .integer("status", status), .text("headers", headers), .text("body", body))
    }
}

/// The host side of this document's typed `<invoke type="sce-host-http-fetch">`s (SCE
/// Accepted Subset §2.12). Register it with `registerStaticHostHttpSceHostHttpFetchInvoker`.
public protocol StaticHostHttpSceHostHttpFetchInvoker: AnyObject {
    /// §scxml-6.4: begin `<invoke id="fetch">`. `token` names this start; a
    /// host that finishes later hands it back to `completeStaticHostHttpFetch`
    /// (or `completeHostInvoke`). A non-nil answer completes the invocation now.
    func startFetch(_ request: StaticHostHttpFetchRequest, token: UInt64) -> StaticHostHttpFetchResult?

    /// §scxml-6.4: `<invoke id="fetch">`'s state exited while the start `token`
    /// names was still running. Stop it.
    func cancelFetch(token: UInt64)

}

/// Registers `invoker` as the handler for `type="sce-host-http-fetch"`.
public func registerStaticHostHttpSceHostHttpFetchInvoker(on engine: Engine<StaticHostHttpPolicy>, invoker: StaticHostHttpSceHostHttpFetchInvoker) {
    engine.registerInvoker("sce-host-http-fetch") { event in
        switch event {
        case .start(let start):
            if start.invokeID.utf8.elementsEqual("fetch".utf8) {
                let typed = StaticHostHttpFetchRequest(method: start.requestString("method"), url: start.requestString("url"), headers: start.requestString("headers"), body: start.requestString("body"))
                if let result = invoker.startFetch(typed, token: start.token) {
                    return .done(result.wire)
                }
                return nil
            }
            return nil
        case .cancel(let cancel):
            if cancel.invokeID.utf8.elementsEqual("fetch".utf8) {
                invoker.cancelFetch(token: cancel.token)
                return nil
            }
            return nil
        }
    }
}

/// Completes `<invoke id="fetch">`'s start `token` with its record:
/// `completeHostInvoke` with the record's JSON, so a stale or unknown token is
/// refused the same way (false).
@discardableResult
public func completeStaticHostHttpFetch(on engine: Engine<StaticHostHttpPolicy>, token: UInt64, result: StaticHostHttpFetchResult) -> Bool {
    engine.completeHostInvoke(processorType: "sce-host-http-fetch", invokeID: "fetch", token: token, doneData: result.wire)
}
